        if (self.highlights) |hl| {
            for (hl) |h| allocator.free(h);
            allocator.free(hl);
        }
        if (self.highlight_scores) |hs| allocator.free(hs);
    }

    pub fn format(self: Result, comptime fmt: []const u8, options: std.fmt.FormatOptions, writer: anytype) !void {
